// 新源→原Common实际cache/history→永久绑定；历史只反查这次结果，不挑同tick更早旧销约。
#include "task_personal_cancellation_receipts.hpp"
#include "task_personal_cancellation_detail.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {namespace {
using namespace personal_cancellation_detail;
Status matches(const TaskPersonalCancellationRecord& s,const StableId& actor,const StableId& kind,const ReceiptDetails& details,Integer tick){const auto* effect=std::get_if<InteractionEffect>(&details.data);if(kind!=task_personal_cancellation_command||s.carrier_actor_id!=actor||s.tick!=tick||!effect||effect->settlement_result!=s.fact_id||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids)return common_failure("TaskPersonalCancellationActualResultMismatch",s.fact_id);return common_success();}
Status bindings(const CommonStore& c,const TaskPersonalCancellationState& state){if(state.version!=1)return common_failure("UnsupportedTaskPersonalCancellationVersion");std::set<Integer> fact_numbers;for(const auto& row:c.state().facts.rows()){auto colon=row.first.find(':');if(colon==StableId::npos)continue;auto n=serial(c,row.first,row.first.substr(0,colon));if(n)fact_numbers.insert(*n);}Integer previous_result=0,previous_revision=0;std::map<StableId,Integer> requests;
 for(const auto& row:state.cancellations.rows()){const auto& s=row.second;if(!s.actual_result)return common_failure("TaskPersonalCancellationPermanentResultRequired",row.first);const auto& b=*s.actual_result;const auto fact=serial(c,row.first,task_personal_cancelled_kind),result=serial(c,b.result_id,"result");const auto* head=c.state().facts.find(row.first);const auto* request=c.state().request_sequences.find(b.request_actor_id);if(s.fact_id!=row.first||!head||head->id!=row.first||head->kind!=task_personal_cancelled_kind||head->domain!=task_personal_cancellation_module||!fact||!result||*result<=*fact||*fact<=previous_result||fact_numbers.count(*result)||b.request_actor_id!=s.carrier_actor_id||!c.actor(b.request_actor_id)||!request||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*request||b.request_sequence<=requests[b.request_actor_id]||b.command_kind!=task_personal_cancellation_command||b.from_tick!=s.tick||b.result_tick!=s.tick||s.tick<0||s.tick>c.tick()||b.result_revision<=previous_revision||b.result_revision>c.revision())return common_failure("InvalidTaskPersonalCancellationResult",row.first);previous_result=*result;previous_revision=b.result_revision;requests[b.request_actor_id]=b.request_sequence;
  const HistoryRecord* prior=nullptr;const HistoryRecord* lower=nullptr;Integer found=0;for(const auto& h:c.state().history){if(h.result_id==b.result_id){lower=prior;if(++found>1||h.actor_id!=b.request_actor_id||h.kind!=b.command_kind||h.tick!=b.result_tick)return common_failure("TaskPersonalCancellationHistoryMismatch",row.first);}prior=&h;}if(lower){auto n=serial(c,lower->result_id,"result");if(!n||*n>=*fact)return common_failure("TaskPersonalCancellationResultIntervalMismatch",row.first);}
  const auto* cached=c.state().results.find(b.request_actor_id+":"+std::to_string(b.request_sequence));if(cached){if(found!=1||!*cached||!(*cached)->ok||!(*cached)->details||(*cached)->result_id!=b.result_id||(*cached)->revision!=b.result_revision)return common_failure("TaskPersonalCancellationCacheMismatch",row.first);auto valid=matches(s,b.request_actor_id,(*cached)->kind,*(*cached)->details,(*cached)->tick);if(!valid.ok)return valid;}
 }
 return common_success();
}
}
Outcome<StableId> task_personal_cancellation_new_result_source(const TaskPersonalCancellationState& before,const TaskPersonalCancellationState& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details,Integer tick){auto fail=[]()->Outcome<StableId>{return {false,{},common_failure("TaskPersonalCancellationNewSourceRequired").error};};if(before.version!=1||after.version!=1||after.cancellations.size()<before.cancellations.size())return fail();auto old=after;for(std::size_t i=0;i<before.cancellations.size();++i){if(before.cancellations.order()[i]!=after.cancellations.order()[i]||!before.cancellations.rows()[i].second.actual_result)return fail();}std::vector<StableId> fresh(after.cancellations.order().begin()+before.cancellations.size(),after.cancellations.order().end());for(const auto& id:fresh)old.cancellations.erase(id);if(!compare_boundary(encode_task_personal_cancellations(before),encode_task_personal_cancellations(old)).exact())return fail();if(kind!=task_personal_cancellation_command)return fresh.empty()?Outcome<StableId>{true,{},{}}:fail();if(fresh.size()!=1)return fail();const auto* s=after.cancellations.find(fresh.front());if(!s||s->actual_result)return fail();auto valid=matches(*s,actor,kind,details,tick);return valid.ok?Outcome<StableId>{true,fresh.front(),{}}:Outcome<StableId>{false,{},valid.error};}
Status bind_task_personal_cancellation_result(CommonStore& c,TaskPersonalCancellationState& state,const StableId& id,const StableId& actor,Integer request,const CommitResult& result){if(id.empty())return result.kind==task_personal_cancellation_command?common_failure("TaskPersonalCancellationNewSourceRequired"):common_success();auto* s=state.cancellations.find(id);const auto* cached=c.state().results.find(actor+":"+std::to_string(request));const auto* seq=c.state().request_sequences.find(actor);if(!s||s->actual_result||!result.ok||!result.details||result.tick!=c.tick()||result.revision!=c.revision()||!cached||cached->get()!=&result||!seq||*seq!=request||c.state().history.empty())return common_failure("TaskPersonalCancellationActualResultRequired",id);const auto& h=c.state().history.back();if(h.result_id!=result.result_id||h.actor_id!=actor||h.kind!=result.kind||h.tick!=result.tick)return common_failure("TaskPersonalCancellationActualHistoryRequired",id);auto valid=matches(*s,actor,result.kind,*result.details,result.tick);if(!valid.ok)return valid;s->actual_result=TaskPersonalMessageResult{result.result_id,actor,result.kind,request,result.revision,result.tick,result.tick};valid=bindings(c,state);if(!valid.ok)s->actual_result.reset();return valid;}
Status validate_task_personal_cancellation_results(const CommonStore& c,const TaskPersonalCancellationState* state){if(state){auto valid=bindings(c,*state);if(!valid.ok)return valid;}for(const auto& h:c.state().history)if(h.kind==task_personal_cancellation_command){Integer found=0;if(state)for(const auto& row:state->cancellations.rows())if(row.second.actual_result&&row.second.actual_result->result_id==h.result_id)++found;if(found!=1)return common_failure("TaskPersonalCancellationHistorySourceRequired",h.result_id);}
 std::set<StableId> used;for(const auto& row:c.state().results.rows())if(row.second){const auto& result=*row.second;const auto* effect=result.details?std::get_if<InteractionEffect>(&result.details->data):nullptr;const bool marked=effect&&effect->settlement_result.rfind(StableId{task_personal_cancelled_kind}+":",0)==0;if(result.kind!=task_personal_cancellation_command&&!marked)continue;const auto* s=state&&effect?state->cancellations.find(effect->settlement_result):nullptr;if(!s||!s->actual_result||!used.insert(s->fact_id).second||!result.ok||!result.details)return common_failure("TaskPersonalCancellationCachedSourceRequired",row.first);const auto& b=*s->actual_result;if(row.first!=b.request_actor_id+":"+std::to_string(b.request_sequence)||b.result_id!=result.result_id||b.result_revision!=result.revision)return common_failure("TaskPersonalCancellationCachedBindingMismatch",row.first);auto valid=matches(*s,b.request_actor_id,result.kind,*result.details,result.tick);if(!valid.ok)return valid;}
 return common_success();}
Status validate_task_personal_cancellations(const TaskPersonalCancellationSources& x){auto valid=validate_task_personal_cancellation_business(x);return valid.ok?validate_task_personal_cancellation_results(x.delivery.common,&x.state):valid;}
}
